/**
 * ECDICT dictionary database schema and IndexedDB helpers.
 *
 * `public/data/ecdict.json` and `public/data/lemmas.json` are generated by
 * `scripts/build-ecdict.ts`. Their on-disk shape is versioned here because the
 * build script, the importer and the tests all share it.
 *
 * Positional word rows keep the shipped file compact (object keys repeated
 * 50k times would add ~3 MB):
 *
 *   [word, phonetic, translation, pos, tag, exchange]
 */

import { openDatabase, type StoreDefinition } from '@/lib/db/idb';

export const DICT_DB_NAME = 'earworm-dict';
export const DICT_DB_VERSION = 1;
export const DICT_WORDS_STORE = 'words';
export const DICT_META_STORE = 'meta';

/** Meta record key for a completed import. */
export const DICT_META_KEY = 'ecdict';
/** Meta record key for a partially finished import (resume support). */
export const DICT_PROGRESS_KEY = 'ecdict-progress';

/** Compact positional row used in `ecdict.json`. */
export type DictRow = [word: string, phonetic: string, translation: string, pos: string, tag: string, exchange: string];

export type EcdictMeta = {
  schema: 1;
  /** Content hash of the entry list; guards the IndexedDB import. */
  version: string;
  count: number;
  sourceRows: number;
  tagged: number;
  withPhonetic: number;
  withTranslation: number;
  withPos: number;
  withExchange: number;
  /** Build trim parameters, recorded for reproducibility. */
  topN: number;
  maxTranslationChars: number;
};

export type EcdictFile = {
  meta: EcdictMeta;
  entries: DictRow[];
};

export type LemmaMeta = {
  schema: 1;
  /** Content hash of the surface -> lemma map. */
  version: string;
  count: number;
  /** Number of parsed `lemma.en.txt` groups. */
  groups: number;
};

export type LemmaFile = {
  meta: LemmaMeta;
  /** surface form -> lemma headword, both lowercase. */
  map: Record<string, string>;
};

/** Record stored in the `meta` object store. */
export type DictMetaRecord = {
  key: typeof DICT_META_KEY;
  version: string;
  count: number;
  importedAt: number;
};

/** Resume marker written after every committed chunk. */
export type DictProgressRecord = {
  key: typeof DICT_PROGRESS_KEY;
  version: string;
  nextIndex: number;
};

/** Entry shape stored in the `words` object store (keyPath: `word`). */
export type StoredWord = {
  word: string;
  phonetic?: string;
  translation: string;
  pos?: string;
  tag?: string;
  exchange?: string;
  tags: string[];
};

const DICT_STORES: StoreDefinition[] = [
  { name: DICT_WORDS_STORE, keyPath: 'word' },
  { name: DICT_META_STORE, keyPath: 'key' },
];

/** Open (or create) the dictionary database used as the IndexedDB cache. */
export function openDictDatabase(name: string = DICT_DB_NAME): Promise<IDBDatabase> {
  return openDatabase(name, DICT_DB_VERSION, DICT_STORES);
}
